1	import type { RequestHandler } from "express";
2	import type { Db } from "@paperclipai/db";
3	import type { StorageService } from "../storage/types.js";
4	import type { ActorContext, ActorMembership, Handler, RequestCtx } from "./types.js";
5	
6	export interface AdapterDeps {
7	  db: Db;
8	  storage: StorageService;
9	}
10	
11	/**
12	 * Wraps a transport-agnostic {@link Handler} as an Express {@link RequestHandler}.
13	 *
14	 * Bridging notes:
15	 * - `req.body` is already parsed by express.json(); json() returns it directly
16	 *   so the raw body is never re-parsed.
17	 * - Path params come from `req.params`, query params from `req.query`.
18	 * - `req.actor.type === "none"` is normalised to `null` so handlers can do a
19	 *   simple null-check rather than inspecting the string.
20	 * - The Web API `Response` returned by the handler is forwarded to Express `res`
21	 *   by copying status, headers, and body.
22	 */
23	export function expressHandler(handler: Handler, deps: AdapterDeps): RequestHandler {
24	  return async (req, res, next) => {
25	    try {
26	      // Build the base URL from the incoming request. Express provides
27	      // req.hostname and req.originalUrl which together give us a fully-formed
28	      // URL object without needing the raw Host header gymnastics.
29	      const protocol = (req as { protocol?: string }).protocol ?? "http";
30	      const baseUrl = `${protocol}://${req.hostname}`;
31	      const url = new URL(req.originalUrl, baseUrl);
32	
33	      // Translate the Express actor to ActorContext | null. "none" → null.
34	      const expressActor = req.actor;
35	      let actor: ActorContext | null = null;
36	      if (expressActor?.type === "board") {
37	        actor = {
38	          type: "board",
39	          source: expressActor.source as ActorContext["source"],
40	          userId: expressActor.userId ?? "unknown",
41	          userName: (expressActor as { userName?: string | null }).userName ?? null,
42	          userEmail: (expressActor as { userEmail?: string | null }).userEmail ?? null,
43	          isInstanceAdmin: Boolean((expressActor as { isInstanceAdmin?: boolean }).isInstanceAdmin),
44	          companyIds: (expressActor as { companyIds?: string[] }).companyIds,
45	          memberships: (expressActor as { memberships?: ActorMembership[] }).memberships,
46	          keyId: (expressActor as { keyId?: string }).keyId,
47	          runId: expressActor.runId,
48	        };
49	      } else if (expressActor?.type === "agent") {
50	        actor = {
51	          type: "agent",
52	          source: expressActor.source as ActorContext["source"],
53	          agentId: expressActor.agentId ?? "unknown",
54	          companyId: expressActor.companyId ?? "",
55	          keyId: (expressActor as { keyId?: string }).keyId,
56	          runId: expressActor.runId,
57	        };
58	      }
59	
60	      // Build the Web-API-compatible Headers object from Express's incoming
61	      // headers map. Express lowercases all header names, so this is safe.
62	      const headers = new Headers();
63	      for (const [name, value] of Object.entries(req.headers)) {
64	        if (value === undefined) continue;
65	        if (Array.isArray(value)) {
66	          for (const v of value) headers.append(name, v);
67	        } else {
68	          // value is string here; cast required because Object.entries loses
69	          // the discriminated IncomingHttpHeaders union.
70	          headers.set(name, value as string);
71	        }
72	      }
73	
74	      const ctx: RequestCtx = {
75	        method: req.method,
76	        url,
77	        headers,
78	
79	        // Body is already parsed by express.json() — just return the cached
80	        // object rather than re-serialising/re-parsing it.
81	        json<T = unknown>(): Promise<T> {
82	          return Promise.resolve(req.body as T);
83	        },
84	        text(): Promise<string> {
85	          if (typeof req.body === "string") return Promise.resolve(req.body);
86	          return Promise.resolve(JSON.stringify(req.body));
87	        },
88	
89	        param(name: string): string | undefined {
90	          const value = req.params[name];
91	          return value === undefined ? undefined : String(value);
92	        },
93	        query(name: string): string | undefined {
94	          const value = req.query[name];
95	          if (value === undefined) return undefined;
96	          // Express query values can be string | ParsedQs | string[] | ParsedQs[]
97	          // We only surface the first scalar string.
98	          if (typeof value === "string") return value;
99	          if (Array.isArray(value)) {
100	            const first = value[0];
101	            return typeof first === "string" ? first : undefined;
102	          }
103	          return undefined;
104	        },
105	
106	        actor,
107	        db: deps.db,
108	        storage: deps.storage,
109	      };
110	
111	      const response = await handler(ctx);
112	
113	      res.status(response.status);
114	
115	      // Forward response headers (skip ones Express manages itself).
116	      response.headers.forEach((value, name) => {
117	        const lower = name.toLowerCase();
118	        if (lower === "transfer-encoding" || lower === "content-length") return;
119	        res.setHeader(name, value);
120	      });
121	
122	      const body = await response.text();
123	      res.send(body);
124	    } catch (err) {
125	      next(err);
126	    }
127	  };
128	}
